import FeatureSectionV6 from "./feature-section-v6"

export default function Page() {
  return <FeatureSectionV6 />
}

"use client"

import { Warp } from "@paper-design/shaders-react"

import {
  FSV6_WARP,
  FSV6_WARP_COLORS,
  type FeatureShaderTheme,
} from "./features"

type FeatureSectionV6MeshBgProps = FeatureShaderTheme

export function FeatureSectionV6MeshBg({
  offsetX,
  offsetY,
  frame,
}: FeatureSectionV6MeshBgProps) {
  return (
    <div className="fsv6-mesh-frame" aria-hidden>
      <Warp
        className="fsv6-mesh-canvas"
        colors={[...FSV6_WARP_COLORS]}
        distortion={FSV6_WARP.distortion}
        fit="cover"
        frame={frame}
        offsetX={offsetX}
        offsetY={offsetY}
        proportion={FSV6_WARP.proportion}
        rotation={FSV6_WARP.rotation}
        scale={FSV6_WARP.scale}
        shape={FSV6_WARP.shape}
        shapeScale={FSV6_WARP.shapeScale}
        softness={FSV6_WARP.softness}
        speed={FSV6_WARP.speed}
        swirl={FSV6_WARP.swirl}
        swirlIterations={FSV6_WARP.swirlIterations}
      />
    </div>
  )
}

.fsv6-mesh-frame {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.fsv6-mesh-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-width: 100%;
  min-height: 100%;
}

.fsv6-mesh-frame canvas {
  display: block;
  width: 100% !important;
  height: 100% !important;
}

.fsv6-card-scrim {
  background: linear-gradient(
    165deg,
    color-mix(in oklab, #000000 14%, transparent) 0%,
    color-mix(in oklab, #000000 28%, transparent) 100%
  );
}

@media (prefers-reduced-motion: reduce) {
  .fsv6-mesh-frame {
    display: none;
  }

  .fsv6-card-scrim {
    display: none;
  }
}

export const FSV6_WARP_COLORS = [
  "#000000",
  "#ffffff",
  "#000000",
  "#ffffff",
] as const

export const FSV6_WARP = {
  proportion: 0.5,
  softness: 1,
  distortion: 0.09,
  swirl: 0.9,
  swirlIterations: 6,
  shape: "checks" as const,
  shapeScale: 0.25,
  speed: 3,
  scale: 2.5,
  rotation: 1.35,
}

export type FeatureShaderTheme = {
  offsetX: number
  offsetY: number

  frame: number
}

export type FeatureDefinition = {
  id: string
